import sys, math; sys.path.insert(0,'/home/claude/honglifecalc/build')
from enrich_lib import build, table, add_top
P='/ru/transportnyj-nalog.html'

MSK=[(100,12),(125,25),(150,35),(175,45),(200,50),(225,65),(250,75),(1e12,150)]
def rate(hp):
    for h,v in MSK:
        if hp<=h: return v
def tax(hp,m=12,k=1,r=None):
    r=r or rate(hp); return math.floor(hp*r*m/12*k+0.5)
r=lambda x:f"{x:,}".replace(',',' ')+' ₽'

form='''<form class="card" id="form" onsubmit="return false"><h2>Ваши данные</h2><label class="f"><span>Мощность двигателя, л. с.</span><input id="hp" inputmode="decimal" value="150"><small>Смотрите в ПТС или СТС. Если указаны только кВт: л. с. = кВт × 1,35962.</small></label><label class="f"><span>Месяцев владения в году</span><input id="m" inputmode="decimal" value="12"><small>Месяц регистрации до 15-го числа включительно считается полным.</small></label><label class="f"><span>Своя ставка региона, ₽ за л. с. (0 – ставки Москвы)</span><input id="cr" inputmode="decimal" value="0"></label><label class="chk"><input type="checkbox" id="lux"> Автомобиль из перечня Минпромторга (средняя стоимость от 10 млн ₽) – коэффициент 3</label></form>'''

calc='''function calc(){const hp=Math.max(0,num('hp')),m=Math.min(12,Math.max(0,Math.round(num('m')))),k=$('lux').checked?3:1;let r=num('cr'),src='своя ставка';if(!r){src='ставка Москвы';for(const [h,v] of MSK){if(hp<=h){r=v;break}}}
 if(!hp)return big('Транспортный налог',rub(0,0),'введите мощность двигателя');
 const t=Math.round(hp*r*m/12*k);
 return big('Транспортный налог за год',rub(t,0),hp.toLocaleString('ru-RU')+' л. с. × '+r+' ₽'+(m<12?' × '+m+'/12':'')+(k>1?' × 3':''))+kv([['Ставка',r+' ₽ за 1 л. с. ('+src+')'],['Коэффициент владения',m+' из 12 месяцев'],['Повышающий коэффициент',k>1?'3':'нет'],['В месяц (в среднем)',rub(t/12,0)],['Срок уплаты','до 1 декабря следующего года','t']])+'<p class="note">Налог считают в полных рублях. ФНС сама присылает уведомление; льготы и ставки других регионов проверьте на сайте ФНС.</p>'}'''

ex=[]
for hp,lab in [(90,'Небольшой городской автомобиль'),(106,'Седан 1,6 л'),(150,'Кроссовер'),(249,'Мощный седан'),(300,'Внедорожник')]:
    ex.append([lab,f"{hp} л. с.",f"{rate(hp)} ₽",r(tax(hp))])
print(ex, tax(150,7), tax(400,12,3))

base=[['до 100 л. с. включительно','2,5 ₽','12 ₽'],['свыше 100 до 125 л. с.','3,5 ₽','25 ₽'],['свыше 125 до 150 л. с.','3,5 ₽','35 ₽'],
      ['свыше 150 до 175 л. с.','5 ₽','45 ₽'],['свыше 175 до 200 л. с.','5 ₽','50 ₽'],['свыше 200 до 225 л. с.','7,5 ₽','65 ₽'],
      ['свыше 225 до 250 л. с.','7,5 ₽','75 ₽'],['свыше 250 л. с.','15 ₽','150 ₽']]

FAQ=[
("Как рассчитать транспортный налог на машину?","Умножьте мощность в лошадиных силах на ставку региона. Если машина была у вас не весь год, умножьте ещё на число месяцев ÷ 12. Пример для Москвы: 150 л. с. × 35 ₽ = 5 250 ₽ в год."),
("Какой транспортный налог на 150 л. с. в Москве?","5 250 ₽ в год: 150 × 35 ₽. А у машины на 151 л. с. ставка уже 45 ₽, и налог – 6 795 ₽. Поэтому важна каждая лошадиная сила на границе."),
("До какого числа платить транспортный налог?","До 1 декабря следующего года. Налог за 2025 год нужно заплатить до 1 декабря 2026 года, за 2026 год – до 1 декабря 2027 года. Налоговая сама присылает уведомление."),
("Что делать, если машину купили или продали в середине года?","Налог считают за полные месяцы владения. Если машину зарегистрировали до 15-го числа включительно, месяц считается целым. Если сняли с учёта после 15-го – тоже целым. Пример: 150 л. с. в Москве за 7 месяцев – 3 063 ₽."),
("Что такое повышающий коэффициент 3?","Это утроение налога для дорогих машин из перечня Минпромторга. Он действует для машин средней стоимостью от 10 до 15 млн ₽ не старше 10 лет и от 15 млн ₽ не старше 20 лет. Пример: 400 л. с. в Москве: 400 × 150 × 3 = 180 000 ₽."),
("Почему в моём регионе другая ставка?","Ставки устанавливают регионы. Налоговый кодекс даёт базовые ставки, а регион может увеличить или уменьшить их, но не больше чем в 10 раз. Введите ставку своего региона в поле «Своя ставка»."),
("Как перевести киловатты в лошадиные силы?","1 кВт = 1,35962 л. с. Например, 110 кВт – это около 149,6 л. с. В налоговых документах мощность обычно уже указана в л. с."),
]

art='''<h2 id="figures">Ставки транспортного налога: Москва и Налоговый кодекс</h2>
'''+table(['Мощность легкового автомобиля','Базовая ставка НК РФ, ₽ за л. с.','Ставка Москвы, ₽ за л. с.'],base)+'''
<p class="note">Базовые ставки Налогового кодекса делятся на 5 групп, а у Москвы их 8. Регион может изменить базовую ставку, но не больше чем в 10 раз.</p>
<h2 id="ex">Примеры для Москвы</h2>
<div id="examples">'''+table(['Пример','Мощность','Ставка за 1 л. с.','Налог за год'],ex)+'''</div>
<ul><li><b>Машина куплена в июне.</b> 150 л. с. × 35 ₽ × 7/12 = <b>3 063 ₽</b> за 7 месяцев (июнь – декабрь).</li>
<li><b>Дорогой внедорожник из перечня Минпромторга.</b> 400 л. с. × 150 ₽ × 3 = <b>180 000 ₽</b>.</li>
<li><b>Граница 150 л. с.</b> 150 л. с. – 5 250 ₽, а 151 л. с. – 6 795 ₽. Ставка меняется на всю мощность сразу.</li></ul>
<p class="note">Расчёты сделаны формулой этого калькулятора по ставкам Москвы.</p>
<h2 id="how">Как считать: простыми словами</h2>
<p>Пример: машина 106 л. с., Москва, весь год.</p>
<ul><li>Находим строку в таблице: свыше 100 до 125 л. с. – <b>25 ₽</b> за каждую лошадиную силу.</li>
<li>Умножаем: 106 × 25 = <b>2 650 ₽</b> в год.</li></ul>
<p><b>Налоговая база</b> – это мощность двигателя в лошадиных силах (л. с.). <b>Ставка</b> – рубли за одну л. с. Одна ставка применяется ко всей мощности, а не по частям.</p>
<p>Формула: налог = мощность × ставка × (месяцев владения ÷ 12) × повышающий коэффициент.</p>
<h2 id="tips">Советы и частые ошибки</h2>
<ul><li><b>Проверьте ставку своего региона.</b> В калькуляторе по умолчанию ставки Москвы.</li>
<li><b>Посмотрите льготы.</b> Многие регионы дают льготы, например пенсионерам или многодетным. Условия разные.</li>
<li><b>Не ждите письма.</b> Если уведомление не пришло, проверьте личный кабинет налогоплательщика.</li>
<li><b>Округление.</b> Налог считают в полных рублях: 50 копеек и больше округляют вверх.</li></ul>
<h2 id="faq" style="margin-top:22px">Частые вопросы</h2>'''+''.join(f'<h3>{q}</h3><p>{a}</p>' for q,a in FAQ)+'''
<p class="note">Источники (проверено 25 ноября 2026 г.): <a href="https://www.consultant.ru/document/cons_doc_LAW_28165/" rel="nofollow">Налоговый кодекс РФ, гл. 28 (ст. 361, 362, 363)</a>; <a href="https://www.nalog.gov.ru/rn77/taxation/taxes/transport/" rel="nofollow">ФНС России – транспортный налог</a>; <a href="https://www.mos.ru/dfin/documents/" rel="nofollow">Закон г. Москвы от 09.07.2008 № 33 «О транспортном налоге»</a>; <a href="https://www.nalog.gov.ru/rn77/service/tax/" rel="nofollow">ФНС России – ставки и льготы по регионам</a>. Расчёты сделаны формулой этого калькулятора.</p>'''

out=build(P,'Калькулятор транспортного налога 2026 – ставки Москвы и НК РФ',
 'Рассчитайте транспортный налог по мощности: ставки Москвы и Налогового кодекса, неполный год владения, коэффициент 3, срок уплаты 1 декабря.',
 art,FAQ,form=form,calc=calc)
add_top(out,[('Автор','Hong Life Calculators'),('Проверено','25 ноября 2026 г.'),('Источники','Налоговый кодекс РФ, ФНС России, Закон г. Москвы № 33')],
 [('form','Калькулятор'),('figures','Ставки'),('ex','Примеры'),('how','Как считать'),('tips','Советы'),('faq','Частые вопросы')],'Содержание',('#examples','ru'))
print(out)
